  Button(f,"CHẤP NHẬN").PerformClick();await Task.Delay(80);Check(p.Rows[0].Chosen!=null&&((List<Cue>)F(f,"cues"))[0].Text.Contains("didn't"),"Accept applies only the measured proposal shown in the quick editor");Check(F(f,"pendingAi")==p&&Convert.ToString(grid.Rows[0].Cells["aiFix"].Value)=="Hoàn tác","Accepted repair carries its history into the next render and has Undo");
  C(f,"CloseQuickRepair");await (Task)C(f,"RepairInlineCue",0);Check(((List<Cue>)F(f,"cues"))[0].Text.Contains("did not")&&p.Rows[0].Chosen==null,"Undo at the row restores original narration without altering the source file");
